package com.trampolim.api.career;
import java.util.*;import com.trampolim.api.radar.SkillCatalog;import static com.trampolim.api.radar.RadarModel.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;
@RestController public class CareerEligibilityController {
 private final SkillCatalog users;public CareerEligibilityController(SkillCatalog users){this.users=users;}
 public record Check(String regime,Integer age,boolean enrolled,boolean schoolComplete){}
 @GetMapping("/api/public/career/legal-guidance")public Map<String,Object> guidance(){return Map.of("reviewedAt","2026-11-13","notice","Resumo informativo, não é parecer jurídico e não aprova candidatura. Confirme as regras vigentes, o anúncio e a documentação com a instituição de ensino, empregador ou serviço público competente.","regimes",List.of(Map.of("regime","INTERNSHIP","requirements",List.of("É ato educativo supervisionado, não vínculo de emprego por si só","Exige matrícula e frequência regular, termo de compromisso, atividades compatíveis, supervisão e seguro conforme a Lei do Estágio","Para menores de 18 anos, confirme salvaguardas de horário, atividade e frequência escolar"),"source","https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/lei/l11788.htm"),Map.of("regime","APPRENTICESHIP","requirements",List.of("É contrato especial de trabalho ligado a programa de aprendizagem profissional","Regra geral: 14 anos completos a menos de 24; a legislação prevê exceção de idade máxima para pessoa com deficiência, que exige avaliação apropriada","Quando o ensino médio ainda não foi concluído, exige matrícula e frequência escolar; formação e condições de trabalho devem atender às regras específicas","Menores de 18 anos não podem exercer trabalho noturno, perigoso ou insalubre"),"source","https://www.gov.br/trabalho-e-emprego/pt-br/assuntos/aprendizagem-profissional"),Map.of("regime","EMPLOYMENT","requirements",List.of("A idade mínima geral para trabalho é 16 anos, salvo aprendizagem a partir dos 14","Pessoas menores de 18 anos têm proteções especiais; confirme atividade, jornada e condições do local"),"source","https://www.gov.br/trabalho-e-emprego/pt-br/assuntos/inspecao-do-trabalho/areas-de-atuacao/Combate-trabalho-infantil")));}
 @PostMapping("/api/career/eligibility")public Map<String,Object> check(@AuthenticationPrincipal String email,@RequestBody Check input){users.user(email);if(input==null||!Set.of("EMPLOYMENT","INTERNSHIP","APPRENTICESHIP").contains(Objects.toString(input.regime(),""))||input.age()!=null&&(input.age()<0||input.age()>120))bad("Revise os dados informados.");var alerts=new ArrayList<String>();if(input.regime().equals("INTERNSHIP")){if(!input.enrolled())alerts.add("Estágio exige matrícula e frequência escolar regulares; confirme também o termo e a supervisão.");alerts.add("A compatibilidade das atividades, termo, seguro, instituição e regras aplicáveis a menores exige validação humana.");}if(input.regime().equals("APPRENTICESHIP")){if(input.age()==null)alerts.add("A regra geral considera a partir de 14 anos completos e menos de 24; informe a idade se quiser uma orientação geral.");else if(input.age()<14||input.age()>=24)alerts.add("A idade informada está fora da regra geral; exceções legais exigem avaliação humana e não são decididas pelo sistema.");if(!input.schoolComplete()&&!input.enrolled())alerts.add("Se o ensino médio ainda não foi concluído, confira a matrícula e a frequência escolar.");alerts.add("Programa, ocupação, jornada e salvaguardas legais devem ser confirmados pela entidade formadora e empregador.");}if(input.regime().equals("EMPLOYMENT")){if(input.age()==null)alerts.add("A regra geral é trabalho a partir dos 16 anos, salvo aprendizagem profissional a partir dos 14; a plataforma não decide em qual regime um anúncio se enquadra.");if(input.age()!=null&&input.age()<16)alerts.add("A regra geral permite trabalho a partir dos 16 anos; aprendizagem a partir dos 14 segue regime próprio.");if(input.age()!=null&&input.age()<18)alerts.add("Menores de 18 anos não podem exercer atividade noturna, perigosa ou insalubre; há outras proteções aplicáveis.");}return Map.of("status","HUMAN_VALIDATION_REQUIRED","automaticEligibility",false,"storedPersonalData",false,"checks",alerts,"notice","Esta consulta não aprova nem rejeita candidatura. A idade informada é usada apenas nesta resposta e não é armazenada; valide regras, vaga e documentos com instituição, empregador ou serviço competente.");}
}
